export function isWithinWeightLimit( weight: number ): boolean {
  return weight >= 0.5 && weight <= 30;
}

export function hasOpenSeats(Enrolled: number, Capacity: number): boolean {
  return Enrolled < Capacity;
}

export function isSameBookingRef( codeA: string, slotA: string, codeB: string, slotB: string ): boolean {

  if (codeA === codeB && slotA === slotB) {
    return true;
  }
  return false;
}

